INSERT INTO `creature_text` (`entry`, `groupid`, `id`, `text`, `type`, `language`, `probability`, `emote`, `duration`, `sound`, `comment`) VALUES
(58777, 0, 0, 'The ships are aflame! Troops, to the harbor!', 14, 0, 100, 0, 0, 30565, ''),
(58777, 1, 0, 'Avoid or destroy Baldruc\'s Storm Totems.', 41, 0, 100, 0, 0, 0, '');
INSERT INTO `creature_text` (`entry`, `groupid`, `id`, `text`, `type`, `language`, `probability`, `emote`, `duration`, `sound`, `comment`) VALUES
(58787, 0, 0, 'Don\'t get caught in Big Bessa\'s sights.', 41, 0, 100, 0, 0, 0, '');
INSERT INTO `creature_text` (`entry`, `groupid`, `id`, `text`, `type`, `language`, `probability`, `emote`, `duration`, `sound`, `comment`) VALUES
(58816, 0, 0, 'Ah, it\'s about time. Will you free me, or did you have... other ideas?', 12, 0, 100, 1, 0, 31474, ''),
(58816, 1, 0, 'The Captain of the Guard upstairs, Hedric Evencane, should posses a key. Please, make haste. We do not have all night, you know!', 12, 0, 100, 1, 0, 31475, ''),
(58816, 2, 0, 'My thanks! Shall we make our way off this miserable little island?', 12, 0, 100, 0, 0, 31477, ''),
(58816, 3, 0, 'The \"failed\" siege was merely a feint, of course. You didn\'t realize?', 12, 0, 100, 0, 0, 31478, ''),
(58816, 4, 0, 'Even now an airship draws near; its arcane payload will flatten Theramore Isle and everyone still standing upon it.', 12, 0, 100, 0, 0, 31479, ''),
(58816, 5, 0, 'There we go. Should you pass through Silvermoon City, come and say hello, hmmm? Al diel shala...', 12, 0, 100, 0, 0, 31480, '');
INSERT INTO `creature_text` (`entry`, `groupid`, `id`, `text`, `type`, `language`, `probability`, `emote`, `duration`, `sound`, `comment`) VALUES
(58840, 0, 0, '%s draws his sword and shield.', 41, 0, 100, 0, 0, 0, ''),
(58840, 1, 0, '%s drops his shield and draws a dagger.', 41, 0, 100, 0, 0, 0, '');
INSERT INTO `creature_text` (`entry`, `groupid`, `id`, `text`, `type`, `language`, `probability`, `emote`, `duration`, `sound`, `comment`) VALUES
(58870, 0, 0, 'The unthinkable has happened: Our siege on Theramore has failed.', 12, 0, 100, 5, 0, 30642, ''),
(58870, 1, 0, 'You\'re the contingency plan. Your mission is to infiltrate Theramore Isle.', 12, 0, 100, 1, 0, 30643, ''),
(58870, 2, 0, 'Burn their ships. Butcher their flight master. Sabotage their war machines. And rescue our spy!', 12, 0, 100, 25, 0, 30644, '');
