INSERT INTO `creature_text` (`entry`, `groupid`, `id`, `text`, `type`, `language`, `probability`, `emote`, `duration`, `sound`, `comment`) VALUES
(67799, 0, 0, '$p, report for duty immediately!', 14, 0, 100, 0, 0, 0, 'captain intro');
INSERT INTO `creature_text` (`entry`, `groupid`, `id`, `text`, `type`, `language`, `probability`, `emote`, `duration`, `sound`, `comment`) VALUES
(67879, 0, 0, 'Zan\'vess will never fall!', 14, 0, 100, 0, 0, 0, 'telvrak intro');
INSERT INTO `creature_text` (`entry`, `groupid`, `id`, `text`, `type`, `language`, `probability`, `emote`, `duration`, `sound`, `comment`) VALUES
(68831, 0, 0, 'We\'ve got our work cut out for us, $p.', 14, 0, 100, 0, 0, 0, 'nalley intro'),
(68831, 1, 0, 'Shield generators all over the island are protecting the Heart of Zan\'vess, preventing us from reaching the weapons cache.', 14, 0, 100, 0, 0, 0, 'nalley about shields 1'),
(68831, 2, 0, 'If we don\'t get this shield down soon we\'re going to be overrun.', 14, 0, 100, 0, 0, 0, 'nalley about shields 2'),
(68831, 3, 0, 'Aim for those amber bombs, they\'ll cause a huge explosion if we manage to set one off!', 14, 0, 100, 0, 0, 0, 'nalley about thields 3'),
(68831, 4, 0, 'Good shot, $p! Keep aiming for those bombs.', 14, 0, 100, 0, 0, 0, 'nalley hit bombs'),
(68831, 5, 0, 'We\'re going in! Take out those towers!', 14, 0, 100, 0, 0, 0, 'nalley about towers'),
(68831, 6, 0, 'Those Mantid are protecting the towers, $p. Take them out or we won\'t be able to land any shots.', 14, 0, 100, 0, 0, 0, 'nalley protective towers'),
(68831, 7, 0, 'Only a few more towers and that whole thing is coming down!', 14, 0, 100, 0, 0, 0, 'nalley towers'),
(68831, 8, 0, 'Those scorpid are moving the towers! Take them out!', 14, 0, 100, 0, 0, 0, 'nalley scorpid towers'),
(68831, 9, 0, 'The shield is down! Nice work, $p! I\'ll take us to the beachhead.', 14, 0, 100, 0, 0, 0, 'nalley end of');
