INSERT INTO `creature_text` (`entry`, `groupid`, `id`, `text`, `type`, `language`, `probability`, `emote`, `duration`, `sound`, `comment`) VALUES
(71327, 0, 0, 'Avast, these Horde scallywags have made their way onto our ship.  Take care of them!', 14, 0, 100, 0, 0, 0, ''),
(71327, 1, 0, 'Ah, so it\'s a duel you want?  Then a duel you shall have!', 14, 0, 100, 0, 0, 0, ''),
(71327, 2, 0, 'FIRE!', 14, 0, 100, 0, 0, 0, ''),
(71327, 3, 0, 'The Rapier has fallen to the ground.  Pick it up to engage Admiral Hagman!', 41, 0, 100, 0, 0, 0, '');
