INSERT INTO `creature_text` (`entry`, `groupid`, `id`, `text`, `type`, `language`, `probability`, `emote`, `duration`, `sound`, `comment`) VALUES
(71330, 0, 0, 'Watch out!', 14, 0, 100, 0, 0, 0, ''),
(71330, 1, 0, '%s has put a |cFFFF2222|Hspell:132998|h[Sticky Bomb]|h|r on you!', 42, 0, 100, 0, 0, 0, ''),
(71330, 2, 0, '%s begins to drink a |cFFFF2222|Hspell:141327|h[Volatile Concoction]|h|r.', 41, 0, 100, 0, 0, 0, ''),
(71330, 3, 0, 'Let\'s see how this works!', 14, 0, 100, 0, 0, 0, '');
INSERT INTO `creature_text` (`entry`, `groupid`, `id`, `text`, `type`, `language`, `probability`, `emote`, `duration`, `sound`, `comment`) VALUES
(71436, 0, 0, 'These Alliance pigs are swinging aboard.  Fend them off!', 14, 0, 100, 0, 0, 0, ''),
(71436, 1, 0, 'Victory is ours!  Get in the cannon and press the attack!', 14, 0, 100, 0, 0, 0, '');
INSERT INTO `creature_text` (`entry`, `groupid`, `id`, `text`, `type`, `language`, `probability`, `emote`, `duration`, `sound`, `comment`) VALUES
(71445, 0, 0, 'Help us fend off these Alliance dogs!', 14, 0, 100, 0, 0, 0, ''),
(71445, 1, 0, 'More are swinging over.  It looks like this is the last of \'em!', 14, 0, 100, 0, 0, 0, ''),
(71445, 2, 0, 'We\'ve pushed them back to their ship.  Swing over and steal their explosives to blow it to smithereens!', 14, 0, 100, 0, 0, 0, ''),
(71445, 3, 0, 'That\'s the last of them!  Get to the bottom of the ship and plant those explosives!', 14, 0, 100, 0, 0, 0, ''),
(71445, 4, 0, 'The ship is about to explode.  Run to the top deck and swing away!', 41, 0, 100, 0, 0, 0, ''),
