(71445, 13, 0, '5', 41, 0, 100, 0, 0, 0, ''),
(71445, 14, 0, '4', 41, 0, 100, 0, 0, 0, ''),
(71445, 15, 0, '3', 41, 0, 100, 0, 0, 0, ''),
(71445, 16, 0, '2', 41, 0, 100, 0, 0, 0, ''),
(71445, 17, 0, '1', 41, 0, 100, 0, 0, 0, ''),
(71445, 18, 0, 'That\'ll teach \'em!  Now hop in that cannon and converge on their lead ship!', 14, 0, 100, 0, 0, 0, '');
