INSERT INTO `creature_text` (`entry`, `groupid`, `id`, `text`, `type`, `language`, `probability`, `emote`, `duration`, `sound`, `comment`) VALUES
(67569, 0, 0, 'Once you have delivered supplies, your work is not done. Do your best to keep our resources topped off.', 12, 0, 100, 1, 0, 0, ''),
(67569, 1, 0, 'Look fer brittle roots stickin\' out of the soil. There\'s good wood in \'em!', 12, 0, 100, 1, 0, 0, ''),
(67569, 2, 0, 'Food and wood are our primary needs. Speak with me if you seek to aid us further.', 12, 0, 100, 1, 0, 0, '');
INSERT INTO `creature_text` (`entry`, `groupid`, `id`, `text`, `type`, `language`, `probability`, `emote`, `duration`, `sound`, `comment`) VALUES
(67883, 0, 0, 'Gnome Construction Site Under Attack!', 41, 0, 100, 30, 0, 34768, '');
INSERT INTO `creature_text` (`entry`, `groupid`, `id`, `text`, `type`, `language`, `probability`, `emote`, `duration`, `sound`, `comment`) VALUES
(68057, 0, 0, 'Dwarf Construction Site Under Attack!', 41, 0, 100, 30, 0, 34768, '');
INSERT INTO `creature_text` (`entry`, `groupid`, `id`, `text`, `type`, `language`, `probability`, `emote`, `duration`, `sound`, `comment`) VALUES
(68474, 0, 0, 'Alliance dogs! Where are your teeth?', 14, 0, 100, 1, 0, 34476, ''),
(68474, 1, 0, 'Bring up the grunts. Attack!', 14, 0, 100, 1, 0, 34477, ''),
(68474, 2, 0, 'For the warchief!', 14, 0, 100, 1, 0, 34469, ''),
(68474, 3, 0, 'Your Alliance is WEAK!', 14, 0, 100, 0, 0, 34471, ''),
(68474, 4, 0, 'I am done with you!', 14, 0, 100, 1, 0, 34472, ''),
(68474, 5, 0, 'Commander Scargash is filled with rage! Avoid his melee attacks!', 41, 0, 100, 0, 0, 0, ''),
(68474, 6, 0, 'Is this how you fight your battles?', 12, 0, 100, 1, 0, 34470, '');
INSERT INTO `creature_text` (`entry`, `groupid`, `id`, `text`, `type`, `language`, `probability`, `emote`, `duration`, `sound`, `comment`) VALUES
(68599, 0, 0, 'Meet us west of the temple, $rt. We shall require your aid.', 12, 0, 100, 1, 0, 0, ''),
(68599, 1, 0, 'Night Elf Construction Site Under Attack!', 41, 0, 100, 30, 0, 34768, '');
INSERT INTO `creature_text` (`entry`, `groupid`, `id`, `text`, `type`, `language`, `probability`, `emote`, `duration`, `sound`, `comment`) VALUES
(69026, 0, 0, 'You three are my eyes and ears. Fan out! Prepare a defense!', 12, 0, 100, 397, 0, 34690, ''),
(69026, 1, 0, 'Make use of every resource! Leave them nowhere to run!', 12, 0, 100, 1, 0, 0, ''),
(69026, 2, 0, 'Patience, Tyrande.', 12, 0, 100, 1, 0, 0, ''),
(69026, 3, 0, 'We\'re almost ready. Keep on working!', 12, 0, 100, 1, 0, 0, ''),
(69026, 4, 0, 'Ready our defenses. They have to come out eventually.', 12, 0, 100, 1, 0, 0, ''),
(69026, 5, 0, 'This terrain is ours. Make them pay for every inch.', 12, 0, 100, 1, 0, 0, ''),
(69026, 6, 0, 'Patience, Tyrande. We\'ll have our victory, but we\'re not going in unprepared.', 12, 0, 100, 1, 0, 0, ''),
(69026, 7, 0, 'Don\'t charge in. Let them make the first mistake.', 12, 0, 100, 1, 0, 0, ''),
(69026, 8, 0, 'I won\'t throw away Alliance lives. I will accept nothing less than total victory.', 12, 0, 100, 1, 0, 0, ''),
(69026, 9, 0, 'They\'re coming. Get behind the defenses!', 14, 0, 100, 1, 0, 34703, ''),
(69026, 10, 0, 'Come out and count them, coward!', 14, 0, 100, 1, 0, 34704, ''),
(69026, 11, 0, 'There is no army here. Only a handful of heroes stand between you and the King of Stormwind. Are you afraid?', 14, 0, 100, 1, 0, 34705, ''),
(69026, 12, 0, 'The day is ours! And not a drop of blood was shed on holy ground.', 12, 0, 100, 1, 0, 34655, ''),
(69026, 13, 0, 'There was a time where I would have done the same. But I\'ve learned a lot over the years. I\'ve fallen for too many of Garrosh\'s tricks.', 12, 0, 100, 1, 0, 34656, ''),
(69026, 14, 0, 'From now on, we define the terms of the engagement.', 12, 0, 100, 1, 0, 34657, ''),
(69026, 15, 0, 'Tyrande, I may not be a politician. But I am a fighter. I know we can win this war.', 12, 0, 100, 1, 0, 34658, ''),
(69026, 16, 0, 'We just need to stand together. You have to trust me. Know that I will do the right thing. If we act as one, we cannot fail.', 12, 0, 100, 1, 0, 34659, '');
